const cmd=(cmd,max_output_tokens=2000)=>tools.exec_command({login:false,cmd,max_output_tokens});const fetch=(r,path,start_line,end_line)=>tools.mcp__codex_apps__github_fetch_file({repository_full_name:"newsdayads/"+r,path,ref:"main",start_line,end_line});
const jobs={
project:fetch("drivetrack","docs/PROJECT_INSTRUCTIONS.md",1,105),
roadmap:fetch("drivetrack","docs/design/DEXSHOT_MASCOT_ROADMAP.md",1,120),
loader:cmd("$b=gh api 'repos/newsdayads/tigeriq-ai-lab/contents/bootstrap/00_TIGERIQ_LOADER.md?ref=main' | ConvertFrom-Json; $s=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b.content)); $s -split \"`n\" | Select-String -Pattern '^## |bootstrap/0[1-5]|DeX Shot'"),
policy:cmd("gh issue view 504 -R newsdayads/tigeriq-ai-lab --json title,body --jq '.title, (.body | split(\"\\n\") | map(select(test(\"DeX|Codex|NO YAPPING|Owner\"; \"i\"))) | .[0:16][])'"),
dynamic:cmd("$b=gh api 'repos/newsdayads/tigeriq-ai-lab/contents/docs/CURRENT_STATE.md?ref=main' | ConvertFrom-Json; [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b.content)) -split \"`n\" | Select-String -Pattern 'DeX|Driver|^#' | Select-Object -First 25"),
central:cmd("foreach($i in 280,335) { gh issue view $i -R newsdayads/tigeriq-ai-lab --json title,state,updatedAt,body --jq 'del(.body) + {relevant:(.body|split(\"\\n\")|map(select(test(\"DeX Shot|drivetrack\";\"i\")))|.[0:10])}' }"),
pr1395:cmd("gh pr view 1395 -R newsdayads/drivetrack --json title,state,updatedAt,isDraft,headRefName,headRefOid,mergeStateStatus,reviewDecision,statusCheckRollup,body,comments,url",5500),
pr1394:cmd("gh pr view 1394 -R newsdayads/drivetrack --json title,state,mergeCommit,headRefOid,statusCheckRollup,body,comments,url",3000),
pr1391:cmd("gh pr view 1391 -R newsdayads/drivetrack --json title,state,isDraft,headRefOid,mergeStateStatus,statusCheckRollup,body,url",1800),
brain:cmd("entire brain brief 'TigerIQ DeX Shot current GitHub and PC01 release status' --json",500)};
await Promise.allSettled(Object.entries(jobs).map(async ([k,p])=>{try {const r=await p; store(k,r);if(r.output!==undefined)text(k+" "+r.output);else {const s=JSON.stringify(r);text(k+" "+s.slice(0,k==="project"?8200:5200));}}catch(e){text(k+" "+e);}}));

