const cmd=(cmd,max_output_tokens=1800)=>tools.exec_command({login:false,cmd,max_output_tokens});const files=["bootstrap/01_TIGERIQ_COMPANY_CONSTITUTION.md","bootstrap/02_TIGERIQ_WORKFLOW.md","bootstrap/03_TIGERIQ_AI_EMPLOYEE_MODEL.md","bootstrap/05_TIGERIQ_BASELINE_DECISIONS.md","docs/OWNER_INTERACTION_V6.md"];
const dfiles=[".agents/skills/drivetrack-engineering/SKILL.md","docs/DRIVER_RELEASE_REPORT_STANDARD.md",".agents/skills/driver-native-reliability/SKILL.md","docs/DRIVER_OWNER_REQUIREMENTS.md"];
const get=(repo,path)=>tools.mcp__codex_apps__github_fetch_file({repository_full_name:"newsdayads/"+repo,ref:"main",path});
const jobs=[...files.map(f=>[f,get("tigeriq-ai-lab",f)]),...dfiles.map(f=>[f,get("drivetrack",f)]),["live",cmd("curl.exe -fsS --max-time 12 --write-out '\\nHTTP %{http_code}\\n' https://driver.tigeriq.io.vn/release-version.json https://driver.tigeriq.io.vn/healthz")],["routes",cmd("gh api 'repos/newsdayads/drivetrack/git/trees/main?recursive=1' --jq '.tree[].path' | Select-String 'dexshot.*(ota|release|install)|ota.*dexshot|dexshot.*version|de[xX].*[sS]hot.*runbook'")],["search",cmd("gh issue list -R newsdayads/drivetrack --state all --search '\"DeX Shot\" in:title' --limit 15 --json title,number,state,updatedAt,url",2100)],["web",tools.web__run({open:[{ref_id:"https://driver.tigeriq.io.vn/release-version.json"},{ref_id:"https://driver.tigeriq.io.vn/healthz"}],response_length:"short"})]];
await Promise.allSettled(jobs.map(async ([k,p])=>{try{const r=await p;store(k,r);const b=r.structuredContent?.content;if(b){const ls=b.split("\n"); const sel=ls.filter(s=>/^#{1,3} |OTA|dexshot|NO YAPPING|no yapping|evidence/i.test(s));text(k+" "+sel.join("\n").slice(0,2400));}else text(k+" "+JSON.stringify(r).slice(0,3400));}catch(e){text(k+" "+e);}}));text(ALL_TOOLS.filter(x=>/google_drive.*(get_file|metadata|download)/.test(x.name)).map(x=>x.name));

