const cmd=(cmd,max_output_tokens=1600)=>tools.exec_command({login:false,cmd,max_output_tokens});const jobs={
tree:cmd("gh api 'repos/newsdayads/drivetrack/git/trees/main?recursive=1' --jq '.tree[].path' | Select-String 'android-update|apk-release|active-release|driver-server|apk.candidat|update.manifest|dexshot' | Select-Object -First 100"),
review:cmd("gh api 'repos/newsdayads/drivetrack/pulls/1394/comments' --jq '.[] | {path,body,url:.html_url}'"),
checks:cmd("gh api 'repos/newsdayads/drivetrack/commits/5dfe41bb8389be1356d82cbfe1385b13c6b22c99/check-runs' --jq '{total_count,checks:[.check_runs[]|{name,status,conclusion}]}'"),
localota:cmd("$p='D:/TigerIQ/Driver/ops/apk-candidates/active-release.json'; if (Test-Path -LiteralPath $p) { $r=Get-Content -LiteralPath $p -Raw | ConvertFrom-Json; $r.PSObject.Properties | Where-Object Name -Match 'version|code|package|applicationId' | Select-Object Name,Value | ConvertTo-Json -Depth 4 } else { 'Manifest not accessible at canonical local path' }"),
clock:cmd("Get-Date -Format 'yyyy-MM-dd HH:mm:ss zzz'")
};await Promise.allSettled(Object.entries(jobs).map(async ([k,p])=>{try{const r=await p;store(k,r);text(k+" "+r.output);}catch(e){text(k+" "+e);}}));

