package app.tigeriq.dexshot

import android.app.ActivityManager
import android.content.Context
import android.os.Build
import android.os.PowerManager
import android.view.View

internal object DexShotMascotSettings {
    const val MODE_2D = "hq2d"
    const val MODE_3D = "live3d"
    const val WIDTH_DP = 120
    const val HEIGHT_DP = 164
    private const val PREFS = "tigeriq_dexshot_mascot"
    private const val MOTION_KEY = "reduced_motion"

    fun prefs(context: Context) = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    fun getMode(context: Context): String = prefs(context).getString("renderer_mode", MODE_2D)
        ?.takeIf { it == MODE_3D && is3dAvailable(context) } ?: MODE_2D

    fun setMode(context: Context, mode: String) {
        val supported = if (mode == MODE_3D && is3dAvailable(context)) mode else MODE_2D
        prefs(context).edit().putString("renderer_mode", supported).apply()
    }

    const val MODEL_ASSET = "tigeriq-live.glb"
    private const val RENDERER = "app.tigeriq.dexshot.TigerIq3DView"
    private const val FAILURE_EPOCH = "live3d_failure_epoch"
    private var failed = false

    fun is3dAvailable(context: Context): Boolean {
        if (Build.VERSION.SDK_INT < 28 || failed || context.packageName != "app.tigeriq.dexshot") return false
        val gpu = context.getSystemService(ActivityManager::class.java)
        if ((gpu?.deviceConfigurationInfo?.reqGlEsVersion ?: 0) < 0x30000) return false
        return runCatching { context.assets.open(MODEL_ASSET).use { it.read() >= 0 } }.getOrDefault(false)
    }

    fun usePowerSaver(context: Context): Boolean =
        context.getSystemService(PowerManager::class.java)?.isPowerSaveMode == true

    fun newLiveRenderer(context: Context): DexShotLiveRenderer? {
        return try {
            Class.forName(RENDERER).getConstructor(Context::class.java)
                .newInstance(context) as DexShotLiveRenderer
        } catch (_: Exception) {
            mark3dFailure(context)
            null
        } catch (_: LinkageError) {
            mark3dFailure(context)
            null
        }
    }

    fun mark3dFailure(context: Context) {
        if (failed) return
        failed = true
        val prefs = prefs(context)
        prefs.edit().putLong(FAILURE_EPOCH, System.currentTimeMillis()).apply()
    }

    fun isReducedMotion(context: Context): Boolean {
        val prefs = prefs(context)
        val previousStyle = prefs.getString("style", "gif")
