$script=@'

import base64, hashlib, json, math, pathlib, sys, zipfile
from PIL import Image, ImageDraw, ImageFont, ImageFilter

root, capture_path, car_path, old_apk = (pathlib.Path(v) for v in sys.argv[1:5])
root.mkdir(exist_ok=False)
RESAMPLE = Image.Resampling.BICUBIC
FONT = 'C:/Windows/Fonts/arialbd.ttf'
FPS = 30
PLATE = '50E-389.20'

def clamp(x):
    return max(0.0, min(1.0, x))

def smooth(x):
    x = clamp(x)
    return x*x*(3-2*x)

def fit(image, width):
    return image.resize((width, round(image.height * width / image.width)), Image.Resampling.LANCZOS)

def natural_alpha(image):
    assert image.mode == 'RGBA' and image.getchannel('A').getextrema() == (0,255)
    return image

def branded_headset(image):
    # Supply the legible production insignia as a separate composited layer.
    label = Image.new('RGBA', (112, 124))
    d = ImageDraw.Draw(label)
    d.ellipse((20, 17, 92, 107), fill=(14, 25, 34, 252))
    d.text((56, 62), 'TiG', font=ImageFont.truetype(FONT, 34),
           fill=(150, 245, 255, 255), anchor='mm')
    label = label.rotate(20, resample=RESAMPLE, expand=True)
    image.alpha_composite(label, (249-label.width//2, 596-label.height//2))
    return image

def strip_warp(image, beat):
    # Warp the camera and arms together so hands stay attached to the camera and sleeves.
    w,h=image.size
    meshes=[]
    change = 0.36*math.pi
    grids = [(y, beat*math.exp(-((y-.55*h)/(.25*h))**2) *
                 math.sin(change + math.pi*y/h)) for y in range(0,h,8)]
    grids.append((h,0.0))
    for (y0,d0),(y1,d1) in zip(grids, grids[1:]):
        meshes.append(((0,y0,w,y1),(0,y0+d0,0,y1+d1,w,y1+d1,w,y0+d0)))
    return image.transform(image.size, Image.Transform.MESH, meshes, resample=RESAMPLE)

def draw_flash(canvas, x, y, strength):
    effect = Image.new('RGBA', (144,144))
    d=ImageDraw.Draw(effect)
    for radius, opacity in ((61,24),(43,51),(28,96),(14,164),(5,250)):
        d.ellipse((72-radius,72-radius,72+radius,72+radius),
                  fill=(242,250,255,round(opacity*strength)))
    effect=effect.filter(ImageFilter.GaussianBlur(3))
    d = ImageDraw.Draw(effect)
    points=[]
    for i in range(8):
        angle=i*math.pi/4
        radius=(42 if i%2==0 else 5)*(0.65+strength*.35)
        points.append((72+math.cos(angle)*radius,72+math.sin(angle)*radius))
    d.polygon(points, fill=(255,250,219,round(strength*238)))
    canvas.alpha_composite(effect,(x-72,y-72))

capture = fit(branded_headset(natural_alpha(Image.open(capture_path))), 620)
capture_frames=[]
for i in range(42):
    t=i/FPS
    ready=smooth(t/.28)
    recoil=math.exp(-((t-.395)/.047)**2)
    # Starts already recognizable, settles with the camera held visibly at the end.
    displacement=-30*(1-ready)-4*recoil+1.5*math.sin(2.1*t)
    frame=Image.new('RGBA',(720,640))
    pose=strip_warp(capture, displacement).rotate((1-ready)*-3.7+1.1*recoil,
                                                   RESAMPLE, expand=True)
    x=(720-pose.width)//2+round(5*(1-ready))
    y=640-pose.height-14+round(7*(1-ready))
    frame.alpha_composite(pose,(x,y))
    flash=max(0.0, 1.0-abs((t-.383)/.055))
    if flash:
        draw_flash(frame,488,348,flash)
    capture_frames.append(frame)

def add_plate(car):
    plate = Image.new('RGBA',(186,58))
    d=ImageDraw.Draw(plate)
    d.text((93,29), PLATE, font=ImageFont.truetype(FONT,33),
           fill=(21,23,18,255), anchor='mm', stroke_width=0)
    plate=plate.rotate(2.0,RESAMPLE,expand=True)
    car.alpha_composite(plate,(1553-plate.width//2,609-plate.height//2))
    return car

vehicle = fit(add_plate(natural_alpha(Image.open(car_path))), 720)
scale=vehicle.width/1774
wheels=[]
for cx,cy,rx,ry in [(195,644,65,97),(986,679,82,111)]:
    left,top=round((cx-rx)*scale),round((cy-ry)*scale)
    ww,hh=round(2*rx*scale),round(2*ry*scale)
    square=vehicle.crop((left,top,left+ww,top+hh)).resize((120,120),RESAMPLE)
    mask=Image.new('L',(120,120))
    ImageDraw.Draw(mask).ellipse((4,4,115,115),fill=255)
    mask=mask.filter(ImageFilter.GaussianBlur(1.9)).resize((ww,hh),Image.Resampling.LANCZOS)
    wheels.append((left,top,ww,hh,square,mask))

drive_frames=[]
positions=[]
for i in range(108):
    t=i/(108-1)
    phase = .14*smooth(t/.24)+.72*t+.14*smooth((t-.76)/.24)
    x=42+round(446*phase)
    y=58+round(.9*math.sin(t*math.pi*7)*math.sin(t*math.pi))
    frame=Image.new('RGBA',(1280,450))
    car=vehicle.copy()
    for left,top,w,h,square,mask in wheels:
        angle=-math.degrees((x-42)/max(w,h)*1.44)
        rim=square.rotate(angle,RESAMPLE).resize((w,h),RESAMPLE)
        car.paste(rim,(left,top),mask)
    shadow=Image.new('RGBA',(780,53))
    ImageDraw.Draw(shadow).ellipse((37,12,748,37),fill=(5,8,12,70))
    shadow=shadow.filter(ImageFilter.GaussianBlur(8))
    frame.alpha_composite(shadow,(x-30,y+vehicle.height-31))
    frame.alpha_composite(car,(x,y))
    drive_frames.append(frame)
    positions.append(x)
assert positions==sorted(positions) and positions[-1]-positions[0]>=440

def save_webp(frames, path):
    times=[round((i+1)*1000/FPS)-round(i*1000/FPS) for i in range(len(frames))]
    frames[0].save(path, format='WEBP', append_images=frames[1:], save_all=True,
        duration=times, loop=1, quality=90, alpha_quality=100, method=4)
    with Image.open(path) as preview:
        assert preview.is_animated and preview.size==frames[0].size
        n=preview.n_frames
        durations=[]
        for i in range(n):
            preview.seek(i)
            preview.load()
            durations.append(preview.info['duration'])
        assert sum(durations)==sum(times) and n>=len(frames)*.88
        assert preview.mode=='RGBA'
    return dict(frames=n, ms=sum(durations), size=frames[0].size,
                sha=hashlib.sha256(path.read_bytes()).hexdigest())

capt_file=root/'capture.webp'
drive_file=root/'drive.webp'
results={'capture':save_webp(capture_frames,capt_file),
         'drive':save_webp(drive_frames,drive_file)}
capture_frames[10].save(root/'capture-frame.png')
drive_frames[54].save(root/'drive-frame.png')

assert hashlib.sha256(old_apk.read_bytes()).hexdigest()=='9b738a303cd94c5b3494ee7ef306947dfbd828dd73ab4e6d8ad6281cfe263c7b'
with zipfile.ZipFile(old_apk) as z:
    old={k:z.read(f'assets/tigeriq-paired/{k}.webp') for k in results}
sources={k:[base64.b64encode(old[k]).decode(),base64.b64encode(p.read_bytes()).decode()] for k,p in
         {'capture':capt_file,'drive':drive_file}.items()}

