package app.tigeriq.dexshot

import java.util.Locale
import kotlin.math.ceil

/** Only real uploader phases and its messages can choose a success/duplicate scene. */
internal object DexShotVisualSpec {
    // All effects have a paired 2.5D asset and 3D clip. DRIVING is visual-only.
    enum class Scene(val clip: String, val loops: Boolean) {
        READY("idle", true),
        CAPTURING("capture", false),
        SAVED("saved", false),
        COUNTDOWN("countdown", true),
        UPLOADING("upload", true),
        RECEIVED("received", false),
        PROCESSING("analyze", true),
        RECONCILING("reconcile", true),
        SUCCESS("success", false),
        REVIEW("warning", true),
        RETRY("retry", false),
        DUPLICATE("duplicate", false),
        DRIVING("drive", true)
    }

    const val DRIVE_AFTER_MS = 8_000L
    const val DRIVE_DURATION_MS = 4_000L
    const val BLEND_MS = 200L

    data class Presentation(val scene: Scene, val speech: String, val color: Int) {
        val showSpeech: Boolean get() = speech.isNotBlank()
    }

    private val TEAL = 0xFF2DD4BF.toInt()
    private val GREEN = 0xFF36E69E.toInt()
    private val AMBER = 0xFFFAC36D.toInt()
    private val RED = 0xFFFF877B.toInt()

    private fun isDuplicate(message: String, badge: String): Boolean {
        val text = "$message $badge".lowercase(Locale.ROOT)
        return listOf("trùng", "duplicate", "đã tồn tại", "bỏ qua ảnh trùng", "trùng lặp")
            .any(text::contains)
    }

    fun resolve(phase: Int, message: String, badge: String, count: Int,
                deadlineMs: Long, nowMs: Long): Presentation {
        val detail = message.trim()
        val lower = detail.lowercase(Locale.ROOT)
        return when (phase) {
            DexShotState.PHASE_READY -> Presentation(Scene.READY, "", TEAL)
            DexShotState.PHASE_CAPTURING -> Presentation(Scene.CAPTURING, "Đang chụp màn hình…", TEAL)
            DexShotState.PHASE_SAVED -> Presentation(Scene.SAVED,
                detail.ifBlank { "Đã lưu ${count.coerceAtLeast(1)} ảnh trên máy" }, GREEN)
            DexShotState.PHASE_RECEIVED -> Presentation(Scene.RECEIVED,
                detail.ifBlank { "PC01 đã nhận ảnh · chờ AI đối chiếu" }, TEAL)
            DexShotState.PHASE_COUNTDOWN -> {
                val remaining = ceil((deadlineMs - nowMs).coerceAtLeast(0L) / 1000.0).toInt()
                Presentation(Scene.COUNTDOWN,
                    "Đã lưu ${count.coerceAtLeast(1)} ảnh · chờ gửi ${remaining}s", TEAL)
            }
            DexShotState.PHASE_UPLOADING -> Presentation(Scene.UPLOADING,
                detail.ifBlank { "Đang gửi ảnh lên PC01…" }, TEAL)
            DexShotState.PHASE_PROCESSING -> {
                val compare = listOf("đối chiếu", "đối soát", "database", "kiểm chứng db")
                    .any(lower::contains)
                Presentation(if (compare) Scene.RECONCILING else Scene.PROCESSING,
                    detail.ifBlank { if (compare) "Đang đối chiếu OCR / DB…" else "AI đang đọc ảnh…" }, TEAL)
            }
            DexShotState.PHASE_COMPLETE -> {
                if (isDuplicate(detail, badge)) Presentation(Scene.DUPLICATE,
                    detail.ifBlank { "Phát hiện ảnh trùng · không ghi thêm" }, AMBER)
                else Presentation(Scene.SUCCESS, detail.ifBlank { "Đã xử lý ảnh thành công." }, GREEN)
            }
            DexShotState.PHASE_REVIEW -> {
                if (isDuplicate(detail, badge)) Presentation(Scene.DUPLICATE,
                    detail.ifBlank { "Ảnh trùng · không ghi thêm" }, AMBER)
                else Presentation(Scene.REVIEW,
                    detail.ifBlank { "Chưa đủ chứng cứ · cần xem lại" }, AMBER)
            }
            else -> Presentation(Scene.RETRY,
                detail.ifBlank { "Không xử lý được ảnh · cần kiểm tra lại" }, RED)
        }
    }

    fun preview(scene: Scene): Presentation = when (scene) {
        Scene.READY, Scene.DRIVING -> Presentation(scene, "", TEAL)
        Scene.CAPTURING -> Presentation(scene, "Đang chụp ảnh…", TEAL)
        Scene.SAVED -> Presentation(scene, "Đã lưu 1 ảnh", GREEN)
        Scene.RECEIVED -> Presentation(scene, "PC01 đã nhận đủ 1 ảnh", TEAL)
        Scene.COUNTDOWN -> Presentation(scene, "Đã chụp 1 ảnh · chờ 7s", TEAL)
        Scene.UPLOADING -> Presentation(scene, "Đang gửi ảnh lên PC01…", TEAL)
        Scene.PROCESSING -> Presentation(scene, "AI đang đọc 1 ảnh…", TEAL)
        Scene.RECONCILING -> Presentation(scene, "Đang đối chiếu OCR / DB…", TEAL)
        Scene.SUCCESS -> Presentation(scene, "Đã lưu cuốc thành công", GREEN)
        Scene.REVIEW -> Presentation(scene, "Thiếu chứng cứ · giữ REVIEW", AMBER)
        Scene.RETRY -> Presentation(scene, "Lỗi đọc ảnh · thử lại", RED)
        Scene.DUPLICATE -> Presentation(scene, "Phát hiện trùng · bỏ qua", AMBER)
    }
}

