class DexCaptureService : Service() {
    companion object {
        const val ACTION_START = "app.tigeriq.dexshot.START"
        const val ACTION_CAPTURE = "app.tigeriq.dexshot.CAPTURE"
        const val ACTION_SHOW_OVERLAY = "app.tigeriq.dexshot.SHOW_OVERLAY"
        const val ACTION_STOP = "app.tigeriq.dexshot.STOP"
        const val ACTION_STATUS = "app.tigeriq.dexshot.STATUS"
        const val EXTRA_RESULT_CODE = "resultCode"
        const val EXTRA_RESULT_DATA = "resultData"
        const val EXTRA_WIDTH = "width"
        const val EXTRA_HEIGHT = "height"
        const val EXTRA_DENSITY = "density"
        const val EXTRA_DISPLAY_ID = "displayId"
        const val EXTRA_MESSAGE = "message"
        const val EXTRA_OVERLAY_READY = "overlayReady"
        const val ACTION_DELIVERY_RECEIPT = "app.tigeriq.flipshot.DELIVERY_RECEIPT"
        private const val CHANNEL_ID = "tigeriq_dexshot_capture"
        private const val NOTIFICATION_ID = 7318
        private const val PREFS = "tigeriq_dexshot_overlay"
        private const val PREF_X = "x"
        private const val PREF_Y = "y"

        @Volatile private var projectionReady = false
        @Volatile private var projectionDisplayId = Display.INVALID_DISPLAY
        @Volatile private var overlayReady = false
        fun isProjectionReady(): Boolean = projectionReady
        fun isProjectionReadyFor(id: Int): Boolean = projectionReady && projectionDisplayId == id
        fun isOverlayReady(): Boolean = overlayReady
    }

    private val flipMode: Boolean get() = packageName == "app.tigeriq.flipshot"
    private val shotName: String get() = if (flipMode) "TigerIQ Flip Shot" else "TigerIQ DeX Shot"

    private var projection: MediaProjection? = null
    private var virtualDisplay: VirtualDisplay? = null
    private var imageReader: ImageReader? = null
    private var width = 0
    private var height = 0
    private var density = 0
    private var displayId = Display.DEFAULT_DISPLAY

    private var overlayWindowManager: WindowManager? = null
    private var overlayView: View? = null
    private var statusStateListener: DexShotState.Listener? = null
    private var statusTicker: Runnable? = null
    private val captureRequested = AtomicBoolean(false)
    private val captureTapLocked = AtomicBoolean(false)
    // The DeX connection is a single shift session. Check once when this
    // projection service starts, not on every capture tap.
    private val shiftStartupStarted = AtomicBoolean(false)
    @Volatile private var shiftStartupResult: DexShotUploader.ShiftCheckResult? = null
    private val pendingReceipts = java.util.Collections.newSetFromMap(ConcurrentHashMap<String, Boolean>())
    private val pendingUriGrants = ConcurrentHashMap<String, Uri>()
    private var receiptReceiverRegistered = false
    private val receiptReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            if (intent?.action != ACTION_DELIVERY_RECEIPT || !flipMode) return
            val id = intent.getStringExtra("capture_id") ?: return
            if (!pendingReceipts.remove(id)) return
            pendingUriGrants.remove(id)?.let { uri ->
                runCatching { revokeUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION) }
            }
            val accepted = intent.getBooleanExtra("accepted", false)
            val info = if (accepted)
                "✓ APK TigerIQ Driver đã nhận ảnh. Mở APK Driver để OCR; Chrome không tự nhận ảnh."
            else
                "Ảnh đã lưu nhưng APK Driver từ chối nhận. Mở APK Driver để kiểm tra."
            mainHandler.post {
                if (accepted) highlightBubble(Color.rgb(24, 168, 120))
                else highlightBubble(Color.rgb(220, 96, 36))
                Toast.makeText(this@DexCaptureService, info, Toast.LENGTH_LONG).show()
                sendStatus(info, overlayReady)
            }
        }
    }
    private val workerThread = HandlerThread("TigerIQ-DexShot").apply { start() }
    private val worker = Handler(workerThread.looper)
    // Service property initializers run before attachBaseContext; never use Context.mainLooper here.
    private val mainHandler = Handler(Looper.getMainLooper())
    // Keep a bounded last frame as a fallback when One UI does not emit a new
    // MediaProjection frame after the non-focusable overlay is hidden.
    private val frameLock = Any()
    private var cachedFrame: Bitmap? = null
    private var lastCachedFrameAt = 0L
    private fun clearCachedFrame() = synchronized(frameLock) {
        cachedFrame?.recycle()
        cachedFrame = null
        lastCachedFrameAt = 0L
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onCreate() {
        super.onCreate()
        ensureNotificationChannel()
        if (flipMode) {
            val filter = IntentFilter(ACTION_DELIVERY_RECEIPT)
            val permission = "app.tigeriq.drivetrack.permission.RECEIVE_DEXSHOT"
            ContextCompat.registerReceiver(this, receiptReceiver, filter,
                permission, null, ContextCompat.RECEIVER_EXPORTED)
            receiptReceiverRegistered = true
        }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_START -> {
                if (!flipMode) checkSonShiftOnStartup()
                startProjection(intent)
            }
            ACTION_CAPTURE -> triggerCaptureWithShiftCheck(null)
            ACTION_SHOW_OVERLAY -> {
                val requested = intent.getIntExtra(EXTRA_DISPLAY_ID, displayId)
                if (isProjectionReadyFor(requested)) mainHandler.post { showFloatingButton() }
                else sendStatus("Chưa có quyền chụp trên màn đã chọn.", false)
            }
            ACTION_STOP -> stopSelfSafely(if (flipMode) "Đã dừng TigerIQ Flip Shot." else "Đã dừng TigerIQ DeX Shot.")
        }
        return START_NOT_STICKY
    }

    private fun startProjection(intent: Intent) {
        val requestedDisplayId = intent.getIntExtra(EXTRA_DISPLAY_ID,
            if (flipMode) Display.DEFAULT_DISPLAY else Display.INVALID_DISPLAY)
        if (projectionReady) {
            if (isProjectionReadyFor(requestedDisplayId)) mainHandler.post { showFloatingButton() }
            else sendStatus("Dừng nút nổi trên màn cũ trước khi đổi màn chụp.", false)
            return
        }
        val targetDisplay = resolveCaptureDisplay(requestedDisplayId)
        if (targetDisplay == null) {
            sendStatus("Không xác định được màn chụp đã chọn.", false)
            stopSelf()
            return
        }
        displayId = targetDisplay.displayId
        if (displayId == Display.DEFAULT_DISPLAY) {
            @Suppress("DEPRECATION")
            val metrics = android.util.DisplayMetrics().also { targetDisplay.getRealMetrics(it) }
            width = metrics.widthPixels
            height = metrics.heightPixels
            density = metrics.densityDpi.coerceAtLeast(1)
        } else {
            val mode = targetDisplay.mode
            width = mode.physicalWidth
            height = mode.physicalHeight
            density = createDisplayContext(targetDisplay).resources.displayMetrics.densityDpi.coerceAtLeast(1)
        }

        val notification = buildNotification("Đang bật nút chụp nổi")
        if (Build.VERSION.SDK_INT >= 29) {
            startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION)
        } else {
            startForeground(NOTIFICATION_ID, notification)
        }

        val resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, 0)
        val resultData = if (Build.VERSION.SDK_INT >= 33) {
            intent.getParcelableExtra(EXTRA_RESULT_DATA, Intent::class.java)
        } else {
            @Suppress("DEPRECATION")
            intent.getParcelableExtra(EXTRA_RESULT_DATA)
        }
        if (resultData == null) {
            sendStatus("Thiếu quyền chụp màn hình.", false)
            stopSelfSafely(null)
            return
        }

        try {
            val manager = getSystemService(MediaProjectionManager::class.java)
            val mediaProjection = manager.getMediaProjection(resultCode, resultData)
            projection = mediaProjection
            mediaProjection.registerCallback(object : MediaProjection.Callback() {
                override fun onStop() {
                    projectionReady = false
                    overlayReady = false
                    captureRequested.set(false)
                    captureTapLocked.set(false)
                    worker.post { clearCachedFrame() }
                    mainHandler.post { removeFloatingButton() }
                    runCatching { virtualDisplay?.release() }
                    virtualDisplay = null
                    runCatching { imageReader?.close() }
                    imageReader = null
                    projection = null
                    sendStatus("Quyền chụp màn hình đã dừng.", false)
                    stopSelf()
                }
            }, worker)

            imageReader = ImageReader.newInstance(width, height, PixelFormat.RGBA_8888, 3).also { reader ->
                reader.setOnImageAvailableListener({ source ->
                    val image = runCatching { source.acquireLatestImage() }.getOrNull() ?: return@setOnImageAvailableListener
                    if (captureRequested.compareAndSet(true, false)) {
                        saveCapture(image)
                    } else {
                        rememberFrame(image)
                    }
                }, worker)
            }
            virtualDisplay = mediaProjection.createVirtualDisplay(
                "TigerIQ-DexShot",
                width,
                height,
                density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                imageReader!!.surface,
                null,
                worker,
            )
            projectionDisplayId = displayId
            projectionReady = true
            mainHandler.post { showFloatingButton() }
        } catch (error: Throwable) {
            projectionReady = false
            overlayReady = false
            sendStatus("Không khởi động được chụp màn hình: ${error.message ?: "unknown"}", false)
            stopSelfSafely(null)
        }
    }

    private fun resolveCaptureDisplay(requestedDisplayId: Int): Display? {
        val manager = getSystemService(DisplayManager::class.java)
        val expected = if (flipMode) Display.DEFAULT_DISPLAY else requestedDisplayId
        return manager.getDisplay(expected)?.takeIf { it.state == Display.STATE_ON }
    }

    private fun targetScreenName(): String = when {
        flipMode -> "Z Flip"
        displayId == Display.DEFAULT_DISPLAY -> "điện thoại"
        else -> "Samsung DeX"
    }

    private fun showFloatingButton() {
        if (!projectionReady) {
            sendStatus("Chưa có quyền chụp màn hình.", false)
            return
        }
        if (!Settings.canDrawOverlays(this)) {
            overlayReady = false
            sendStatus("Cần cấp quyền “Hiển thị trên ứng dụng khác”.", false)
            return
        }
        val targetDisplay = resolveCaptureDisplay(displayId)
        if (targetDisplay == null) {
            overlayReady = false
            sendStatus("Không còn thấy màn ${targetScreenName()}.", false)
            return
        }
        displayId = targetDisplay.displayId
        if (overlayView != null) {
            overlayView?.visibility = View.VISIBLE
            overlayReady = true
            sendStatus("Nút T đang hoạt động trên màn ${targetScreenName()}.", true)
            return
        }

        try {
            val displayContext = if (flipMode) this else createDisplayContext(targetDisplay)
            val type = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
            } else {
                @Suppress("DEPRECATION")
                WindowManager.LayoutParams.TYPE_PHONE
            }
            // Samsung DeX Dual Mode requires the WindowManager that belongs to the
            // desktop Display context. Using the service/default-display WindowManager
            // can succeed without ever placing the overlay on the DeX desktop.
            val wm = displayContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager
            val metrics = displayContext.resources.displayMetrics
            // Fixed mascot anchor on the selected display.
            val bubbleWidth = (DexShotMascotSettings.WIDTH_DP * metrics.density).toInt()
            val bubbleHeight = (DexShotMascotSettings.HEIGHT_DP * metrics.density).toInt()
            val margin = (12f * metrics.density).toInt()
            val speechWidth = minOf((232f * metrics.density).toInt(),
                (width - bubbleWidth - margin * 2).coerceAtLeast((100f * metrics.density).toInt()))
            val speechGap = (7f * metrics.density).toInt()
            // Z Flip foldable touch jitter must not turn a tap into an accidental drag.
            val touchSlop = if (flipMode) max(ViewConfiguration.get(displayContext).scaledTouchSlop,
                (24f * metrics.density).toInt())
                else ViewConfiguration.get(displayContext).scaledTouchSlop
            val maxX = max(0, width - bubbleWidth)
            val maxY = max(0, height - bubbleHeight)
            val prefs = getSharedPreferences(PREFS, MODE_PRIVATE)
            val anchorX = margin.coerceIn(0, maxX) // Owner-fixed LEFT; do not restore old right-edge X

            val params = WindowManager.LayoutParams(
                WindowManager.LayoutParams.WRAP_CONTENT,
                WindowManager.LayoutParams.WRAP_CONTENT,
                type,
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                    WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL or
                    WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN or
                    WindowManager.LayoutParams.FLAG_SPLIT_TOUCH or
                    (if (flipMode) 0 else WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED),
                PixelFormat.TRANSLUCENT,
            ).apply {
                gravity = Gravity.TOP or Gravity.START
                x = anchorX
                y = prefs.getInt(PREF_Y, margin * 4).coerceIn(0, maxY)
            }

            val container = LinearLayout(displayContext).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.TOP or Gravity.START
                clipChildren = false
                clipToPadding = false
            }

            val bubble = DexShotBubbleView(displayContext).apply {
                elevation = 8f * metrics.density
            }

            val statusPill = DexShotStatusCard(displayContext)
            val pillLp = LinearLayout.LayoutParams(
                speechWidth, LinearLayout.LayoutParams.WRAP_CONTENT
            ).apply {
                marginStart = speechGap
                topMargin = (7f * metrics.density).toInt()
            }
            container.addView(bubble, LinearLayout.LayoutParams(bubbleWidth, bubbleHeight))
            container.addView(statusPill, pillLp)

            // Fixed left corner, vertical drag only. Status can expand without
            // relocating the mascot or moving the capture touch target.
            val placeBubble = {
                params.x = anchorX
                if (overlayView === container) runCatching { wm.updateViewLayout(container, params) }
            }

            val renderStatusPill = {
                val now = System.currentTimeMillis()
                val capturedCount = DexShotState.getCapturedCount()
                val deadline = DexShotState.getDeadlineAt()
                val visual = DexShotVisualSpec.resolve(
                    DexShotState.getPhase(), DexShotState.getMessage(), DexShotState.getBadge(),
                    capturedCount, deadline, now
                )
                statusPill.render(visual, capturedCount, deadline - now)
                placeBubble()
            }
            val ticker = object : Runnable {
                override fun run() {
                    if (overlayView == null) return
                    renderStatusPill()
                    if (DexShotState.getPhase() == DexShotState.PHASE_COUNTDOWN) {
                        mainHandler.postDelayed(this, 400L)
                    }
                }
            }
            val listener = DexShotState.Listener {
                renderStatusPill()
                mainHandler.removeCallbacks(ticker)
                if (DexShotState.getPhase() == DexShotState.PHASE_COUNTDOWN) {
                    mainHandler.postDelayed(ticker, 400L)
                }
            }
            statusTicker = ticker
            statusStateListener = listener
            DexShotState.bind(listener)

            var startX = 0
            var startY = 0
            var downRawX = 0f
            var downRawY = 0f
            var moved = false
            var longTriggered = false
            val longPressTask = Runnable {
                longTriggered = true
                val phase = DexShotState.getPhase()
                val msg = DexShotState.getMessage()
                if (!DexShotUploader.hasSessionCookie(this@DexCaptureService)) {
                    startActivity(Intent(this@DexCaptureService, DexShotLoginActivity::class.java).apply {
                        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                    })
                    return@Runnable
                }
                if (phase == DexShotState.PHASE_ERROR) {
                    val lower = msg.lowercase(Locale.ROOT)
                    val isAuth = lower.contains("đăng nhập") || lower.contains("401") || lower.contains("403") || lower.contains("hết hạn")
                    if (msg.isNotBlank()) Toast.makeText(this@DexCaptureService, msg, Toast.LENGTH_LONG).show()
                    if (isAuth) {
                        startActivity(Intent(this@DexCaptureService, DexShotLoginActivity::class.java).apply {
                            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                        })
                    }
                    return@Runnable
                }
                val toastText = if (msg.isNotBlank()) msg else if (phase == DexShotState.PHASE_READY) "Nút T DeX sẵn sàng. Chạm nhanh để chụp AI." else "Ảnh DeX đang xử lý..."
                Toast.makeText(this@DexCaptureService, toastText, Toast.LENGTH_LONG).show()
            }
            bubble.setOnTouchListener { view, event ->
                when (event.actionMasked) {
                    MotionEvent.ACTION_DOWN -> {
                        startX = anchorX
                        startY = params.y
                        downRawX = event.rawX
                        downRawY = event.rawY
                        moved = false
                        longTriggered = false
                        mainHandler.removeCallbacks(longPressTask)
                        mainHandler.postDelayed(longPressTask, 650L)
                        true
                    }
                    MotionEvent.ACTION_MOVE -> {
                        val dx = event.rawX - downRawX
                        val dy = event.rawY - downRawY
                        if (abs(dx) > touchSlop || abs(dy) > touchSlop) {
                            moved = true
                            mainHandler.removeCallbacks(longPressTask)
                        }
                        if (moved || !flipMode) {
                            // x remains pinned left, regardless of horizontal gesture.
                            params.y = (startY + dy.toInt()).coerceIn(0, maxY)
                            placeBubble()
                        }
                        true
                    }
                    MotionEvent.ACTION_UP -> {
                        mainHandler.removeCallbacks(longPressTask)
                        if (moved) {
                            prefs.edit().putInt(PREF_Y, params.y).apply()
                        } else if (!longTriggered) {
                            if (!DexShotUploader.hasSessionCookie(this@DexCaptureService)) {
                                DexShotState.update(this@DexCaptureService, DexShotState.PHASE_ERROR, "!", "Cần đăng nhập TigerIQ AI.")
                                startActivity(Intent(this@DexCaptureService, DexShotLoginActivity::class.java).apply {
                                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                                })
                            } else {
                                triggerCaptureWithShiftCheck(view)
                            }
                        }
                        true
                    }
                    MotionEvent.ACTION_CANCEL -> {
                        mainHandler.removeCallbacks(longPressTask)
                        false
                    }
                    else -> false
                }
            }

            wm.addView(container, params)
            overlayWindowManager = wm
            overlayView = container
            placeBubble()
            overlayReady = true
            sendStatus("Nút T đã bật trên màn ${targetScreenName()}.", true)
        } catch (error: Throwable) {
            overlayWindowManager = null
            overlayView = null
            overlayReady = false
            sendStatus("Không tạo được nút T: ${error.message ?: "unknown"}", false)
        }
    }

    private fun checkSonShiftOnStartup() {
        if (!shiftStartupStarted.compareAndSet(false, true)) return
        worker.post {
            val result = DexShotUploader.checkSonShiftOpen(this@DexCaptureService)
            shiftStartupResult = result
            if (!result.open) mainHandler.post {
                DexShotState.update(this@DexCaptureService, DexShotState.PHASE_REVIEW, "CA", result.message)
                Toast.makeText(this@DexCaptureService, result.message, Toast.LENGTH_LONG).show()
            }
        }
    }

    private fun triggerCaptureWithShiftCheck(tapView: View?) {
        val runCapture = {
            if (flipMode) {
                tapView?.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP)
                if (captureTapLocked.compareAndSet(false, true)) requestCapture()
            } else if (tapView != null) {
                pressCaptureFeedback(tapView)
            } else {
                if (captureTapLocked.compareAndSet(false, true)) requestCapture()
            }
        }
        if (!flipMode) {
            val shift = shiftStartupResult
            if (shift == null) {
                Toast.makeText(this, "Đang kiểm tra Ca khi kết nối DeX.", Toast.LENGTH_SHORT).show()
                return
            }
            if (!shift.open) {
                DexShotState.update(this, DexShotState.PHASE_REVIEW, "CA", shift.message)
                Toast.makeText(this, shift.message, Toast.LENGTH_LONG).show()
                return
            }
            runCapture()
            return
        }
        if (DexShotState.getPhase() == DexShotState.PHASE_COUNTDOWN) {
            runCapture()
            return
        }
        worker.post {
            val shift = DexShotUploader.checkSonShiftOpen(this@DexCaptureService)
            mainHandler.post {
                if (!shift.open) {
                    DexShotState.update(this@DexCaptureService, DexShotState.PHASE_REVIEW, "CA", shift.message)
                    Toast.makeText(this@DexCaptureService, shift.message, Toast.LENGTH_LONG).show()
                } else {
                    runCapture()
                }
            }
        }
    }

    private fun requestCapture() {
        if (!projectionReady || !overlayReady) {
            captureTapLocked.set(false)
            sendStatus("Nút T chưa sẵn sàng.", false)
            return
        }
        if (!flipMode && resolveCaptureDisplay(displayId) == null) {
            captureTapLocked.set(false)
            removeFloatingButton()
            sendStatus("Màn chụp đã ngắt kết nối.", false)
            return
        }
        if (captureRequested.get()) {
            captureTapLocked.set(false)
            return
        }
        mainHandler.post {
            if (DexShotState.getPhase() != DexShotState.PHASE_COUNTDOWN &&
                DexShotState.getPhase() != DexShotState.PHASE_SAVED) {
                DexShotState.update(this, DexShotState.PHASE_CAPTURING, "", "Đang chụp màn hình…")
            }
            if (displayId == Display.DEFAULT_DISPLAY) {
                // IMPORTANT: the overlay becoming INVISIBLE itself causes the next
                // MediaProjection frame. Arm the ImageReader BEFORE hiding it.
                // Previously the 120ms delay discarded this one frame on static
                // screens, leaving the orange T and never delivering an image.
                captureRequested.set(true)
                overlayView?.visibility = View.INVISIBLE
                sendStatus("Đã chạm T · đang lấy ảnh từ màn hình...", true)
                mainHandler.postDelayed({
                    if (captureRequested.compareAndSet(true, false)) {
                        // Static screens on some One UI builds do not redraw a
                        // frame after overlay hide. Use the latest buffered
                        // projection frame rather than silently dropping a tap.
                        worker.post {
                            val fallback = runCatching { synchronized(frameLock) {
                                cachedFrame?.takeIf { !it.isRecycled &&
                                    android.os.SystemClock.uptimeMillis() - lastCachedFrameAt <= 2_000L }
                                    ?.copy(Bitmap.Config.ARGB_8888, false)
                            } }.getOrNull()
                            if (fallback != null) {
                                mainHandler.post { overlayView?.visibility = View.VISIBLE }
                                saveBitmap(fallback, "cached-frame")
                            } else {
                                mainHandler.post {
                                    captureTapLocked.set(false)
                                    overlayView?.visibility = View.VISIBLE
                                    flashErrorFeedback()
                                    Toast.makeText(this, "Chưa nhận được ảnh. Mở Flip Shot và cấp lại quyền chụp Toàn bộ màn hình.", Toast.LENGTH_LONG).show()
                                    sendStatus("Không có khung hình · cần cấp lại quyền MediaProjection.", true)
                                }
                            }
                        }
                    }
                }, 900)
            } else {
                // Preserve original working Samsung DeX capture behavior.
                overlayView?.visibility = View.INVISIBLE
                mainHandler.postDelayed({
                    if (!projectionReady || captureRequested.get()) {
                        captureTapLocked.set(false)
                        overlayView?.visibility = View.VISIBLE
                        return@postDelayed
                    }
                    captureRequested.set(true)
                    mainHandler.postDelayed({
                        if (captureRequested.compareAndSet(true, false)) {
                            worker.post {
                                val fallback = runCatching { synchronized(frameLock) {
                                    cachedFrame?.takeIf { !it.isRecycled &&
                                    android.os.SystemClock.uptimeMillis() - lastCachedFrameAt <= 2_000L }
                                        ?.copy(Bitmap.Config.ARGB_8888, false)
                                } }.getOrNull()
                                if (fallback != null) {
                                    mainHandler.post { overlayView?.visibility = View.VISIBLE }
                                saveBitmap(fallback, "cached-frame")
                                } else {
                                    mainHandler.post {
                                        captureTapLocked.set(false)
                                        overlayView?.visibility = View.VISIBLE
                                        flashErrorFeedback()
                                        Toast.makeText(this, "Chưa nhận được khung hình · bấm lại.", Toast.LENGTH_SHORT).show()
                                        sendStatus("Chưa nhận được khung hình · bấm lại.", true)
                                    }
                                }
                            }
                        }
                    }, 1200)
                }, 120)
            }
        }
    }

    private fun pressCaptureFeedback(view: View) {
        if (!captureTapLocked.compareAndSet(false, true)) return
        view.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP)
        view.animate().cancel()
        view.animate().scaleX(0.97f).scaleY(0.97f).setDuration(65L).withEndAction {
            view.animate().scaleX(1f).scaleY(1f).setDuration(65L).withEndAction { requestCapture() }.start()
        }.start()
    }

    private fun imageBitmap(image: Image): Bitmap {
        val plane = image.planes.firstOrNull() ?: error("NO_IMAGE_PLANE")
        val buffer = plane.buffer
        buffer.rewind()
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowPadding = rowStride - pixelStride * width
        val paddedWidth = width + rowPadding / pixelStride
        val padded = Bitmap.createBitmap(paddedWidth, height, Bitmap.Config.ARGB_8888)
        padded.copyPixelsFromBuffer(buffer)
        return if (paddedWidth == width) padded else
            Bitmap.createBitmap(padded, 0, 0, width, height).also { padded.recycle() }
    }

    private fun rememberFrame(image: Image) {
        try {
            val now = android.os.SystemClock.uptimeMillis()
            if (now - lastCachedFrameAt < 750L) return
            val fresh = imageBitmap(image)
            synchronized(frameLock) {
                cachedFrame?.recycle()
                cachedFrame = fresh
                lastCachedFrameAt = now
            }
        } catch (error: Throwable) {
            android.util.Log.w("TigerIQFlipShot", "Unable to buffer projection frame", error)
        } finally {
            image.close()
        }
    }

    private fun saveCapture(image: Image) {
        try {
            // Restore the mascot immediately after the MediaProjection pixels are isolated.
            // Album/queue disk writes must never hold the entire overlay invisible.
            val capturedPixels = imageBitmap(image)
            mainHandler.post { overlayView?.visibility = View.VISIBLE }
            saveBitmap(capturedPixels, "live-frame")
        } catch (error: Throwable) {
            mainHandler.post {
                captureTapLocked.set(false)
                overlayView?.visibility = View.VISIBLE
                flashErrorFeedback()
                Toast.makeText(this, "Lỗi đọc ảnh: ${error.message ?: "unknown"}", Toast.LENGTH_LONG).show()
                sendStatus("Chụp ảnh lỗi: ${error.message ?: "unknown"}", overlayReady)
            }
        } finally {
            image.close()
        }
    }

    private fun saveBitmap(bitmap: Bitmap, source: String) {
        try {
            val displayName = "TigerIQ_DexShot_" + SimpleDateFormat("yyyyMMdd_HHmmss_SSS", Locale.US).format(Date()) + ".jpg"
            saveToDevice(bitmap, displayName)
            val batchId = DexShotState.getOrCreateActiveBatchId()
            DexShotQueue.enqueueBitmap(this, bitmap, batchId)
            // Only the disposable projection-frame cache is cleared; never photo queue or album.
            worker.post { clearCachedFrame() }
            mainHandler.post {
                overlayView?.visibility = View.VISIBLE
                flashSuccessFeedback()
                DexShotState.captured(this, batchId)
                Toast.makeText(this, "Đã chụp & lưu album · chờ 12s gửi AI", Toast.LENGTH_SHORT).show()
            }
            sendStatus("✓ Đã chụp · lưu máy · đang chờ gửi AI.", true)
        } catch (error: Throwable) {
            mainHandler.post {
                overlayView?.visibility = View.VISIBLE
                flashErrorFeedback()
                Toast.makeText(this, "Lỗi lưu/gửi ảnh: ${error.message ?: "unknown"}", Toast.LENGTH_LONG).show()
            }
            sendStatus("Chụp ảnh lỗi: ${error.message ?: "unknown"}", overlayReady)
        } finally {
            bitmap.recycle()
            captureTapLocked.set(false)
        }
    }

    private fun saveToDevice(bitmap: Bitmap, displayName: String): Uri? {
        return if (Build.VERSION.SDK_INT >= 29) {
            val values = ContentValues().apply {
                put(MediaStore.Images.Media.DISPLAY_NAME, displayName)
                put(MediaStore.Images.Media.MIME_TYPE, "image/jpeg")
                put(MediaStore.Images.Media.RELATIVE_PATH, "${Environment.DIRECTORY_PICTURES}/TigerIQ Dex Shot")
                put(MediaStore.Images.Media.IS_PENDING, 1)
            }
            val collection = MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val uri = contentResolver.insert(collection, values) ?: return null
            try {
                contentResolver.openOutputStream(uri, "w")?.use { out ->
                    if (!bitmap.compress(Bitmap.CompressFormat.JPEG, 92, out)) error("JPEG_WRITE_FAILED")
                } ?: error("MEDIASTORE_STREAM_FAILED")
                values.clear()
                values.put(MediaStore.Images.Media.IS_PENDING, 0)
                contentResolver.update(uri, values, null, null)
                uri
            } catch (error: Throwable) {
                contentResolver.delete(uri, null, null)
                throw error
            }
        } else {
            @Suppress("DEPRECATION")
            val folder = File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES), "TigerIQ Dex Shot").apply { mkdirs() }
            val file = File(folder, displayName)
            file.outputStream().use { out ->
                if (!bitmap.compress(Bitmap.CompressFormat.JPEG, 92, out)) error("JPEG_WRITE_FAILED")
            }
            @Suppress("DEPRECATION")
            sendBroadcast(Intent(Intent.ACTION_MEDIA_SCANNER_SCAN_FILE, Uri.fromFile(file)))
            Uri.fromFile(file)
        }
    }

    private fun highlightBubble(color: Int) {
        val bubble = overlayView ?: return
        if (flipMode) bubble.background = GradientDrawable().apply {
            setColor(Color.TRANSPARENT)
            setStroke((3f * resources.displayMetrics.density).toInt().coerceAtLeast(2), color)
            cornerRadius = bubble.width.coerceAtLeast(32) / 2f
        }
    }

    private fun sendToDriver(uri: Uri, displayName: String) {
        val receiptId = if (flipMode) UUID.randomUUID().toString() else ""
        val intent = Intent("app.tigeriq.drivetrack.DEXSHOT_CAPTURE_READY").apply {
            setClassName("app.tigeriq.drivetrack", "app.tigeriq.drivetrack.DexShotCaptureReceiver")
            data = uri
            clipData = ClipData.newRawUri("TigerIQ Dex Shot", uri)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            putExtra("uri", uri)
            putExtra("name", displayName)
            if (receiptId.isNotEmpty()) putExtra("capture_id", receiptId)
        }
        if (receiptId.isNotEmpty()) pendingReceipts.add(receiptId)
        // Make a targeted, temporary grant explicit. Some One UI versions
        // reject reads of MediaStore URIs delivered via implicit URI grants.
        val granted = runCatching {
            grantUriPermission("app.tigeriq.drivetrack", uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }.isSuccess
        if (receiptId.isNotEmpty() && granted) pendingUriGrants[receiptId] = uri
        android.util.Log.i("TigerIQFlipShot", "URI grant=$granted; sending capture to signed Driver")
        val sent = runCatching { sendBroadcast(intent) }.isSuccess
        if (!sent && receiptId.isNotEmpty()) {
            pendingReceipts.remove(receiptId)
            pendingUriGrants.remove(receiptId)?.let { grantedUri ->
                runCatching { revokeUriPermission(grantedUri, Intent.FLAG_GRANT_READ_URI_PERMISSION) }
            }
            mainHandler.post {
                highlightBubble(Color.rgb(220, 96, 36))
                Toast.makeText(this, "Lỗi gửi ảnh sang APK TigerIQ Driver.", Toast.LENGTH_LONG).show()
            }
        } else if (receiptId.isNotEmpty()) {
            mainHandler.postDelayed({
                if (pendingReceipts.remove(receiptId)) {
                    pendingUriGrants.remove(receiptId)?.let { grantedUri ->
                        runCatching { revokeUriPermission(grantedUri, Intent.FLAG_GRANT_READ_URI_PERMISSION) }
                    }
                    highlightBubble(Color.rgb(220, 96, 36))
                    val message = "Ảnh đã lưu nhưng Driver chưa xác nhận. Kiểm tra đã cài APK TigerIQ Driver trên Z Flip, không phải Chrome."
                    Toast.makeText(this, message, Toast.LENGTH_LONG).show()
                    sendStatus(message, overlayReady)
                }
            }, 7000)
        }
    }

    private fun flashSuccessFeedback() {
        val view = overlayView ?: return
        view.animate().cancel()
        view.visibility = View.VISIBLE
        if (!flipMode) return
        view.alpha = 0.25f
        view.scaleX = 0.78f
        view.scaleY = 0.78f
        view.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(180L).start()
    }

    private fun flashErrorFeedback() {
        val view = overlayView ?: return
        view.animate().cancel()
        view.visibility = View.VISIBLE
        if (!flipMode) {
            view.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)
            return
        }
        view.alpha = 0.55f
        view.scaleX = 1.12f
        view.scaleY = 1.12f
        view.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)
        view.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(180L).start()
    }

    private fun removeFloatingButton() {
        statusTicker?.let { mainHandler.removeCallbacks(it) }
        statusTicker = null
        statusStateListener?.let { DexShotState.unbind(it) }
        statusStateListener = null
        val wm = overlayWindowManager
        val view = overlayView
        if (wm != null && view != null) runCatching { wm.removeView(view) }
        overlayView = null
        overlayWindowManager = null
        overlayReady = false
    }

    private fun sendStatus(message: String, ready: Boolean) {
        if (flipMode) getSharedPreferences("flipshot_state", MODE_PRIVATE).edit()
            .putString("last", message)
            .putLong("lastAt", System.currentTimeMillis()).apply()
        sendBroadcast(
            Intent(ACTION_STATUS)
                .setPackage(packageName)
                .putExtra(EXTRA_MESSAGE, message)
                .putExtra(EXTRA_OVERLAY_READY, ready)
        )
    }

    private fun buildNotification(text: String): Notification =
        NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(if (flipMode) R.drawable.flipshot_camera else android.R.drawable.ic_menu_camera)
            .setContentTitle(shotName)
            .setContentText(text)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .build()

    private fun ensureNotificationChannel() {
        if (Build.VERSION.SDK_INT < 26) return
        getSystemService(NotificationManager::class.java).createNotificationChannel(
            NotificationChannel(CHANNEL_ID, "TigerIQ DeX Shot", NotificationManager.IMPORTANCE_LOW)
        )
    }

    private fun stopSelfSafely(message: String?) {
        projectionReady = false
        overlayReady = false
        captureRequested.set(false)
        captureTapLocked.set(false)
        mainHandler.post { removeFloatingButton() }
        runCatching { virtualDisplay?.release() }
        virtualDisplay = null
        runCatching { imageReader?.close() }
        imageReader = null
        val current = projection
        projection = null
        worker.post { clearCachedFrame() }
        if (current != null) runCatching { current.stop() }
        message?.let { sendStatus(it, false) }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) stopForeground(STOP_FOREGROUND_REMOVE)
        else @Suppress("DEPRECATION") stopForeground(true)
        stopSelf()
    }

    override fun onDestroy() {
        projectionReady = false
        overlayReady = false
        mainHandler.post { removeFloatingButton() }
        runCatching { virtualDisplay?.release() }
        virtualDisplay = null
        runCatching { imageReader?.close() }
        imageReader = null
        projection = null
        worker.post { clearCachedFrame() }
        pendingReceipts.clear()
        pendingUriGrants.values.forEach { runCatching {
            revokeUriPermission(it, Intent.FLAG_GRANT_READ_URI_PERMISSION)
        } }
        pendingUriGrants.clear()
        if (receiptReceiverRegistered) runCatching { unregisterReceiver(receiptReceiver) }
        workerThread.quitSafely()
        super.onDestroy()
    }
}

package app.tigeriq.dexshot

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.content.SharedPreferences
import android.graphics.Canvas
import android.graphics.Movie
import android.graphics.ImageDecoder
import android.graphics.drawable.AnimatedImageDrawable
import android.os.Build
import android.graphics.drawable.Drawable
import android.os.PowerManager
import android.os.SystemClock
import android.view.View
import android.widget.FrameLayout
import androidx.core.content.ContextCompat

/** Standalone mascot and idle effects. The status card always uses the actual shot state. */
class DexShotBubbleView(context: Context) : FrameLayout(context), DexShotState.Listener {
    private val fallback: Drawable? =
        ContextCompat.getDrawable(context, R.drawable.tigeriq_dexshot_launcher_hq)?.mutate()
    private val cache = HashMap<Int, Movie>()
    private val highQualityCache = HashMap<DexShotVisualSpec.Scene, Drawable>()
    private val failedDecodes = HashSet<DexShotVisualSpec.Scene>()
    private val pairedDecodes = HashSet<DexShotVisualSpec.Scene>()
    private var highQualityScene: DexShotVisualSpec.Scene? = null
    private var highQualityPreviousScene: DexShotVisualSpec.Scene? = null
    private var playingScene: DexShotVisualSpec.Scene? = null
    private var highQualityTransitionAt = 0L
    private val power = context.getSystemService(Context.POWER_SERVICE) as PowerManager
    private val prefs = DexShotMascotSettings.prefs(context)
    private val flipMode = context.packageName == "app.tigeriq.flipshot"
    private var live: DexShotLiveRenderer? = null
    private var liveFrameReady = false
    private val batteryListener = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            refreshMascotStyle()
        }
    }
    private val preferenceListener = SharedPreferences.OnSharedPreferenceChangeListener { _, _ ->
        refreshMascotStyle()
    }
    private var previewScene: DexShotVisualSpec.Scene? = null
    private var driveScheduled = false
    private var idleDriving = false
    private val finishDrive = Runnable {
        idleDriving = false
        syncLive()
        invalidate()
        updateIdleDrive()
    }
    private val beginDrive = Runnable {
        driveScheduled = false
        if (canDrive()) {
            idleDriving = true
            syncLive()
            invalidate()
            postDelayed(finishDrive, DexShotVisualSpec.DRIVE_DURATION_MS)
        }
    }
    private var shownRes = 0
    private var animationStartedAt = 0L
    private var previousRes = 0
    private var previousStartedAt = 0L
    private var transitionAt = 0L
    private val transitionMs = 320L

    private val ticker = object : Runnable {
        override fun run() {
            if (!isAttachedToWindow) return
            if (!renderVisible() || Build.VERSION.SDK_INT >= 28) return
            if (motionStyle() == "gif") invalidate()
            postDelayed(this, if (power.isPowerSaveMode) 170L else 50L)
        }
    }

    init {
        contentDescription = "TigerIQ DeX Shot · chạm để chụp"
        isClickable = true
        isFocusable = false
        setWillNotDraw(false)
        // Modern animated WebP uses a hardware-capable ImageDecoder; only legacy GIF needs software.
        if (Build.VERSION.SDK_INT < 28) setLayerType(LAYER_TYPE_SOFTWARE, null)
    }

    internal fun setPreviewScene(scene: DexShotVisualSpec.Scene) {
        previewScene = scene
        refreshMascotStyle()
    }

    internal fun refreshMascotStyle() {
        updateIdleDrive()
        if (motionStyle() != "gif") stopHighQuality()
        syncLive()
        invalidate()
    }

    private fun currentScene(): DexShotVisualSpec.Scene {
        previewScene?.let { return it }
        val phase = DexShotState.getPhase()
        if (idleDriving && phase == DexShotState.PHASE_READY) return DexShotVisualSpec.Scene.DRIVING
        return DexShotVisualSpec.resolve(phase, DexShotState.getMessage(), DexShotState.getBadge(),
            DexShotState.getCapturedCount(), DexShotState.getDeadlineAt(), System.currentTimeMillis()).scene
    }

    private fun canDrive(): Boolean = !flipMode && Build.VERSION.SDK_INT >= 28 &&
        previewScene == null && renderVisible() && motionStyle() == "gif" &&
        DexShotState.getPhase() == DexShotState.PHASE_READY

    private fun updateIdleDrive() {
        if (!canDrive()) {
            cancelIdleDrive()
        } else if (!idleDriving && !driveScheduled) {
            driveScheduled = true
            postDelayed(beginDrive, DexShotVisualSpec.DRIVE_AFTER_MS)
        }
    }

    private fun cancelIdleDrive() {
        removeCallbacks(beginDrive)
        removeCallbacks(finishDrive)
        driveScheduled = false
        idleDriving = false
    }

    private fun syncLive() {
        if (!renderVisible()) {
            live?.setActive(false)
            return
        }
        val selected = DexShotMascotSettings.getMode(context)
        if (flipMode || selected != DexShotMascotSettings.MODE_3D || power.isPowerSaveMode) {
            removeLive()
            return
        }
        var renderer = live
        if (renderer == null) {
            renderer = DexShotMascotSettings.newLiveRenderer(context)
            if (renderer == null) return
            live = renderer
            renderer.onFirstFrame = {
                liveFrameReady = true
                stopHighQuality()
                invalidate()
            }
            renderer.onFailure = { post { DexShotMascotSettings.mark3dFailure(context) } }
            addView(renderer.view, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))
        }
        renderer.setScene(currentScene(), !DexShotMascotSettings.isReducedMotion(context))
        renderer.setActive(true)
    }

    private fun removeLive() {
        val renderer = live ?: return
        live = null
        liveFrameReady = false
        renderer.onFirstFrame = null
        renderer.onFailure = null
        renderer.dispose()
        removeView(renderer.view)
    }

    private fun motionStyle(): String = if (flipMode) {
        prefs.getString("style", "gif") ?: "gif"
    } else if (DexShotMascotSettings.isReducedMotion(context) || power.isPowerSaveMode) "static" else "gif"

    private fun renderVisible(): Boolean = isAttachedToWindow && isShown &&
        windowVisibility == VISIBLE

    override fun onVisibilityChanged(changedView: View, visibility: Int) {
        super.onVisibilityChanged(changedView, visibility)
        if (isAttachedToWindow) refreshVisibility()
    }

    override fun onWindowVisibilityChanged(visibility: Int) {
        super.onWindowVisibilityChanged(visibility)
        if (isAttachedToWindow) refreshVisibility()
    }

    private fun refreshVisibility() {
        updateIdleDrive()
        removeCallbacks(ticker)
        if (renderVisible()) {
            if (Build.VERSION.SDK_INT < 28) post(ticker)
            invalidate()
        } else stopHighQuality()
        syncLive()
    }

    private fun stopHighQuality() {
        playingScene = null
        if (Build.VERSION.SDK_INT >= 28) {
            highQualityCache.values.forEach { (it as? AnimatedImageDrawable)?.stop() }
        }
    }

    override fun verifyDrawable(who: Drawable): Boolean =
        super.verifyDrawable(who) || highQualityCache.values.any { it === who }

    private fun sceneResource(scene: DexShotVisualSpec.Scene): Int = when (scene) {
        DexShotVisualSpec.Scene.READY, DexShotVisualSpec.Scene.DRIVING -> R.raw.tigeriq_v3_ready
        DexShotVisualSpec.Scene.CAPTURING -> R.raw.tigeriq_v3_capturing
        DexShotVisualSpec.Scene.SAVED -> R.raw.tigeriq_v3_saved
        DexShotVisualSpec.Scene.RECEIVED -> R.raw.tigeriq_v3_received
        DexShotVisualSpec.Scene.COUNTDOWN -> R.raw.tigeriq_v3_countdown
        DexShotVisualSpec.Scene.UPLOADING -> R.raw.tigeriq_v3_uploading
        DexShotVisualSpec.Scene.PROCESSING -> R.raw.tigeriq_v3_processing
        DexShotVisualSpec.Scene.RECONCILING -> R.raw.tigeriq_v3_reconciling
        DexShotVisualSpec.Scene.SUCCESS -> R.raw.tigeriq_v3_success
        DexShotVisualSpec.Scene.REVIEW -> R.raw.tigeriq_v3_review
        DexShotVisualSpec.Scene.RETRY -> R.raw.tigeriq_v3_retry
        DexShotVisualSpec.Scene.DUPLICATE -> R.raw.tigeriq_v3_duplicate
    }

    private fun highQualityResource(scene: DexShotVisualSpec.Scene): Int = when (scene) {
        DexShotVisualSpec.Scene.READY, DexShotVisualSpec.Scene.DRIVING -> R.raw.tigeriq_v4_ready
        DexShotVisualSpec.Scene.CAPTURING -> R.raw.tigeriq_v4_capturing
        DexShotVisualSpec.Scene.SAVED -> R.raw.tigeriq_v4_saved
        DexShotVisualSpec.Scene.COUNTDOWN -> R.raw.tigeriq_v4_countdown
        DexShotVisualSpec.Scene.UPLOADING -> R.raw.tigeriq_v4_uploading
        DexShotVisualSpec.Scene.RECEIVED -> R.raw.tigeriq_v4_received
        DexShotVisualSpec.Scene.PROCESSING -> R.raw.tigeriq_v4_processing
        DexShotVisualSpec.Scene.RECONCILING -> R.raw.tigeriq_v4_reconciling
        DexShotVisualSpec.Scene.SUCCESS -> R.raw.tigeriq_v4_success
        DexShotVisualSpec.Scene.REVIEW -> R.raw.tigeriq_v4_review
        DexShotVisualSpec.Scene.RETRY -> R.raw.tigeriq_v4_retry
        DexShotVisualSpec.Scene.DUPLICATE -> R.raw.tigeriq_v4_duplicate
    }

    private fun animatedFor(scene: DexShotVisualSpec.Scene): AnimatedImageDrawable? {
        if (Build.VERSION.SDK_INT < 28) return null
        highQualityCache[scene]?.let { return it as? AnimatedImageDrawable }
        if (scene in failedDecodes) return null
        val paired = if (flipMode) null else runCatching {
            ImageDecoder.decodeDrawable(ImageDecoder.createSource(context.assets, "tigeriq-paired/${scene.clip}.webp"))
                as? AnimatedImageDrawable
        }.getOrNull()
        val decoded = paired ?: runCatching {
            ImageDecoder.decodeDrawable(ImageDecoder.createSource(resources, highQualityResource(scene)))
                as? AnimatedImageDrawable
        }.getOrNull()
        if (decoded == null) {
            failedDecodes.add(scene)
            return null
        }
        if (paired != null) {
            pairedDecodes.add(scene)
            decoded.repeatCount = if (scene.loops) AnimatedImageDrawable.REPEAT_INFINITE else 0
        }
        decoded.callback = this
        highQualityCache[scene] = decoded
        return decoded
    }

    private fun drawHighQuality(canvas: Canvas, scene: DexShotVisualSpec.Scene,
                                style: String, now: Long): Boolean {
        if (Build.VERSION.SDK_INT < 28) return false
        val incoming = animatedFor(scene) ?: return false
        if (highQualityScene != scene) {
            highQualityPreviousScene = highQualityScene
            highQualityScene = scene
            highQualityTransitionAt = now
            highQualityCache.keys.filter { it != scene && it != highQualityPreviousScene }
                .forEach(::releaseHighQuality)
        }
        val play = style == "gif" && renderVisible()
        if (play && playingScene != scene) {
            incoming.start()
            playingScene = scene
        }
        if (!play) stopHighQuality()

        val blendMs = if (scene in pairedDecodes) DexShotVisualSpec.BLEND_MS else transitionMs
        val elapsed = (now - highQualityTransitionAt).coerceAtLeast(0L)
        val previousScene = highQualityPreviousScene
        val previous = if (play && previousScene != null && elapsed < blendMs)
            highQualityCache[previousScene] else null
        if (previous != null && previousScene != null) {
            val fraction = (elapsed.toFloat() / blendMs).coerceIn(0f, 1f)
            val eased = fraction * fraction * (3f - 2f * fraction)
            drawHighQualityFrame(canvas, previous, previousScene, (255f * (1f - eased)).toInt())
            drawHighQualityFrame(canvas, incoming, scene, (255f * eased).toInt())
            postInvalidateOnAnimation()
        } else {
            previousScene?.let(::releaseHighQuality)
            highQualityPreviousScene = null
            drawHighQualityFrame(canvas, incoming, scene, 255)
        }
        return true
    }

    private fun releaseHighQuality(scene: DexShotVisualSpec.Scene) {
        val drawable = highQualityCache.remove(scene) ?: return
        if (Build.VERSION.SDK_INT >= 28) (drawable as? AnimatedImageDrawable)?.stop()
        unscheduleDrawable(drawable)
        drawable.callback = null
        pairedDecodes.remove(scene)
    }

    private fun drawHighQualityFrame(canvas: Canvas, drawable: Drawable,
                                    scene: DexShotVisualSpec.Scene, alpha: Int) {
        if (alpha <= 0) return
        val w = drawable.intrinsicWidth.coerceAtLeast(1)
        val h = drawable.intrinsicHeight.coerceAtLeast(1)
        val fit = minOf(width.toFloat() / w, height.toFloat() / h)
        // The v4 artwork was exported from three differently zoomed body poses.
        // Calibrate around the common floor line, with the body independent of the effects.
        val useCanonicalFit = flipMode || scene in pairedDecodes
        val artScale = if (useCanonicalFit) 1f else when (scene) {
            DexShotVisualSpec.Scene.UPLOADING, DexShotVisualSpec.Scene.PROCESSING,
            DexShotVisualSpec.Scene.RECONCILING, DexShotVisualSpec.Scene.DUPLICATE -> 1.07f
            DexShotVisualSpec.Scene.CAPTURING, DexShotVisualSpec.Scene.SAVED,
            DexShotVisualSpec.Scene.RECEIVED -> 0.93f
            else -> 0.84f
        }
        val displayWidth = w * fit
        val displayHeight = h * fit
        val left = (width - displayWidth) / 2f
        val top = (height - displayHeight) / 2f
        val bodyOffset = if (flipMode || artScale > 1f) -8f else -28f
        val pivotX = left + displayWidth * 0.36f
        val pivotY = top + displayHeight * (536f / 560f)
        if (alpha < 255) canvas.saveLayerAlpha(0f, 0f, width.toFloat(), height.toFloat(), alpha)
        else canvas.save()
        if (!useCanonicalFit) canvas.translate(bodyOffset * fit, 0f)
        canvas.scale(artScale, artScale, pivotX, pivotY)
        drawable.setBounds(left.toInt(), top.toInt(), (left + displayWidth).toInt(), (top + displayHeight).toInt())
        drawable.draw(canvas)
        canvas.restore()
    }

    private fun drawFallback(canvas: Canvas) {
        val icon = fallback ?: return
        val size = minOf(width, height)
        val left = (width - size) / 2
        val top = (height - size) / 2
        icon.setBounds(left, top, left + size, top + size)
        icon.draw(canvas)
    }

    override fun onStateChanged() {
        val text = DexShotState.getMessage()
        contentDescription = if (text.isBlank()) "TigerIQ DeX Shot · chạm để chụp"
            else "TigerIQ DeX Shot · $text"
        refreshMascotStyle()
    }

    private fun movieFor(res: Int): Movie? {
        cache[res]?.let { return it }
        return runCatching { resources.openRawResource(res).use { Movie.decodeStream(it) } }
            .getOrNull()?.takeIf { it.width() > 0 && it.height() > 0 }
            ?.also { cache[res] = it }
    }

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        // Warm all frames before a tap; avoid the first-frame blank when switching scenes.
        if (Build.VERSION.SDK_INT < 28) DexShotVisualSpec.Scene.values().forEach { movieFor(sceneResource(it)) }
        DexShotState.bind(this)
        prefs.registerOnSharedPreferenceChangeListener(preferenceListener)
        if (!flipMode) ContextCompat.registerReceiver(context, batteryListener,
            IntentFilter(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED), ContextCompat.RECEIVER_NOT_EXPORTED)
        refreshVisibility()
    }

    override fun onDetachedFromWindow() {
        cancelIdleDrive()
        removeCallbacks(ticker)
        prefs.unregisterOnSharedPreferenceChangeListener(preferenceListener)
        if (!flipMode) context.unregisterReceiver(batteryListener)
        removeLive()
        highQualityCache.keys.toList().forEach(::releaseHighQuality)
        failedDecodes.clear()
        highQualityScene = null
        highQualityPreviousScene = null
        playingScene = null
        DexShotState.unbind(this)
        super.onDetachedFromWindow()
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)
        if (width <= 0 || height <= 0 || liveFrameReady) return
        val style = motionStyle()
        if (style == "icon") {
            stopHighQuality()
            drawFallback(canvas)
            return
        }
        val scene = currentScene()
        val res = sceneResource(scene)
        val now = SystemClock.uptimeMillis()
        if (drawHighQuality(canvas, scene, style, now)) return
        if (Build.VERSION.SDK_INT >= 28 && !flipMode) {
            stopHighQuality()
            drawFallback(canvas)
            return
        }
        val incoming = movieFor(res)
        if (shownRes != res && incoming != null) {
            previousRes = shownRes
            previousStartedAt = animationStartedAt
            shownRes = res
            animationStartedAt = now
            transitionAt = now
        }
        if (incoming == null) {
            val previous = movieFor(shownRes)
            if (previous != null) renderMovie(canvas, previous, animationStartedAt, now, style, 255)
            else drawFallback(canvas)
            return
        }
        val elapsed = (now - transitionAt).coerceAtLeast(0L)
        val oldMovie = if (previousRes != 0 && previousRes != res && elapsed < transitionMs)
            movieFor(previousRes) else null
        if (oldMovie != null) {
            val fraction = (elapsed.toFloat() / transitionMs).coerceIn(0f, 1f)
            renderMovie(canvas, oldMovie, previousStartedAt, now, style,
                (255f * (1f - fraction)).toInt().coerceIn(0, 255))
            renderMovie(canvas, incoming, animationStartedAt, now, style,
                (255f * fraction).toInt().coerceIn(0, 255))
        } else {
            previousRes = 0
            renderMovie(canvas, incoming, animationStartedAt, now, style, 255)
        }
    }

    private fun renderMovie(canvas: Canvas, movie: Movie, startedAt: Long,
                            now: Long, style: String, alpha: Int) {
        if (alpha <= 0) return
        val duration = movie.duration().coerceAtLeast(100)
        movie.setTime(if (style == "static") 0 else ((now - startedAt).coerceAtLeast(0L) % duration).toInt())
        val scale = minOf(width.toFloat() / movie.width(), height.toFloat() / movie.height())
        canvas.saveLayerAlpha(0f, 0f, width.toFloat(), height.toFloat(), alpha)
        canvas.translate((width - movie.width() * scale) / 2f,
            (height - movie.height() * scale) / 2f)
        canvas.scale(scale, scale)
        movie.draw(canvas, 0f, 0f)
        canvas.restore()
    }
}

