                        statusCard.render(visual, 1, 7000L)
                    }
                }
                btn.minHeight = dp(52)
                row.addView(btn, LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    marginEnd = dp(4)
                    bottomMargin = dp(6)
                })
            }
            root.addView(row, LinearLayout.LayoutParams(-1, ViewGroup.LayoutParams.WRAP_CONTENT))
        }
        scroll.addView(root)
        setContentView(scroll)
    }
